import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Probe {
    static String clean(String html, Safelist sl) {
        return Jsoup.clean(html, sl);
    }
    static void t(String label, String html, Safelist sl) {
        System.out.println(label + " => " + clean(html, sl));
    }
    public static void main(String[] args) {
        Safelist basic = Safelist.basic();
        Safelist rel = Safelist.basic().preserveRelativeLinks(true);
        Safelist custom = Safelist.none().addTags("a","img","form")
            .addAttributes("a","href").addAttributes("img","src").addAttributes("form","action")
            .addProtocols("a","href","http","https").addProtocols("img","src","http")
            .addProtocols("form","action","https");

        // baseline
        t("js plain",        "<a href=javascript:alert(1)>x</a>", basic);
        t("js upper",        "<a href=JAVAscript:alert(1)>x</a>", basic);
        t("js tab",          "<a href=\"java\tscript:alert(1)\">x</a>", basic);
        t("js nl prefix",    "<a href=\"\njavascript:alert(1)\">x</a>", basic);
        t("js leading ws",   "<a href=\"  javascript:alert(1)\">x</a>", basic);
        t("js entity",       "<a href=\"&#x09;javascript:alert(1)\">x</a>", basic);
        t("js ctrl in proto","<a href=\"java&#x09;script:alert(1)\">x</a>", basic);
        t("js backslash",    "<a href=\"javascript\\\\:alert(1)\">x</a>", basic);
        t("js backslash2",   "<a href=\"javascript:\\\\alert(1)\">x</a>", basic);
        t("data",            "<a href=data:text/html,x>x</a>", basic);
        t("vbscript",        "<a href=vbscript:msgbox(1)>x</a>", basic);
        t("http ok",         "<a href=\"https://example.com/a?b=1#c\">x</a>", basic);
        t("HTTP upper",      "<a href=\"HTTPS://Example.COM/x\">x</a>", basic);
        t("rel path",        "<a href=foo/bar.html>x</a>", rel);
        t("root rel",        "<a href=/foo/bar>x</a>", rel);
        t("fragment",        "<a href=#section>x</a>", rel);
        t("proto-rel",       "<a href=//example.com/x>x</a>", rel);
        t("multi colon",     "<a href=\"http://evil.com/:javascript:x\">x</a>", basic);
        t("js multi colon2", "<a href=\"javascript:x:y\">x</a>", basic);
        t("empty",           "<a href=>x</a>", basic);
        t("noval",           "<a href>x</a>", basic);
        t("tab after colon", "<a href=\"javascript:\talert(1)\">x</a>", basic);
        t("cr nl",           "<a href=\"java\r\nscript:1\">x</a>", basic);
        t("formfeed",        "<a href=\"java script:1\">x</a>", basic);
        t("unicode ws",      "<a href=\"java script:1\">x</a>", basic);
        // independent attrs
        t("multi attr",      "<a href=javascript:1 src=x onclick=y>z</a>",
            Safelist.none().addTags("a").addAttributes("a","href","src","onclick")
                .addProtocols("a","href","http","https").addProtocols("a","src","http","https"));
        t("cross leak",      "<form action=javascript:1><img src=javascript:2></form>", custom);
        // idempotency
        String once = clean("<a href=JavaScript:alert(1)//>x</a>", basic);
        System.out.println("idempotent once: " + once);
        System.out.println("idempotent twice: " + clean(once, basic));
        // backslash tricks via abs url (browsers treat \ as /)
        t("bs scheme",       "<a href=\"javascript\\\\@example.com/\">x</a>", basic);
        t("http bs",         "<a href=\"http:/\\\\evil.com\">x</a>", basic);
        t("js tab colon",    "<a href=\"java\tscript:alert(1)\">x</a>", rel);
        // strange: whitespace before scheme with preserveRelative false (abs resolution path)
        t("ws js abs",       "<a href=\" javascript:1\">x</a>", basic);
        t("nbsp js",         "<a href=\"  javascript:1\">x</a>", basic);
        // data on img
        t("img data",        "<img src=data:image/png;base64,xx>", custom);
        t("img js",          "<img src=javascript:1>", custom);
        t("form js",         "<form action=JAVASCRIPT:1></form>", custom);
    }
}
