import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class Probe2 {
    static Safelist policy() {
        return Safelist.basicWithImages()
            .addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https");
    }
    static void run(String label, String html, String base, boolean rel) {
        try {
            Safelist sl = policy();
            if (rel) sl.preserveRelativeLinks(true);
            Document dirty = Jsoup.parse(html, base);
            Cleaner c = new Cleaner(sl);
            Document clean = c.clean(dirty);
            String out = clean.body().html();
            System.out.println("== " + label + (rel ? " (rel)" : ""));
            System.out.println("   => " + out.replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t").replace("\f", "\\f"));
        } catch (Throwable t) {
            System.out.println("== " + label + " -> THREW " + t);
        }
    }
    public static void main(String[] a) {
        String base = "https://example.com/page/index.html";
        // safe candidate first, dangerous second
        run("safe then js",   "<img srcset='https://ok.com/b.jpg 2x, javascript:alert(1) 1x'>", base, false);
        run("js then safe",   "<img srcset='javascript:alert(1) 1x, https://ok.com/b.jpg 2x'>", base, false);
        run("rel then js",    "<img srcset='/safe.jpg 1x, javascript:alert(1) 2x'>", base, false);
        run("js 2nd relmode", "<img srcset='https://ok.com/b.jpg, javascript:alert(1)'>", base, true);
        run("data 2nd",       "<img srcset='https://ok.com/b.jpg, data:text/html,evil'>", base, false);
        run("case js 2nd",    "<img srcset='https://ok.com/b.jpg, JaVaScRiPt:x'>", base, false);
        run("js no descriptor","<img srcset='https://ok.com/b.jpg,javascript:alert(1)'>", base, false);
        // three candidates, middle dangerous
        run("mid js",         "<img srcset='a.jpg 1x, javascript:x 2x, https://ok.com/c.jpg 3x'>", base, false);
        // trailing comma garbage
        run("trailing comma", "<img srcset='https://ok.com/b.jpg,'>", base, false);
        // only https allowed, http candidate second
        Safelist httpsOnly = Safelist.none().addTags("img")
            .addAttributes("img","srcset").addProtocols("img","srcset","https");
        Document d = Jsoup.parse("<img srcset='https://ok.com/b.jpg, http://insecure.com/a.jpg'>", base);
        System.out.println("== https-only mixed => " + new Cleaner(httpsOnly).clean(d).body().html());
        // href percent-encoded scheme with preserveRelativeLinks
        Safelist relBasic = Safelist.basic().preserveRelativeLinks(true);
        System.out.println("== href pct js rel => [" + Jsoup.clean("<a href=java%73cript:alert(1)>x</a>", relBasic) + "]");
        System.out.println("== href DEL rel    => [" + Jsoup.clean("<a href=java\u007fscript:alert(1)>x</a>", relBasic) + "]");
        System.out.println("== href js rel     => [" + Jsoup.clean("<a href=javascript:alert(1)>x</a>", relBasic) + "]");
    }
}

