/**
 Test that every URL candidate carried by the attribute value uses an allowed protocol. Single-valued URL
 attributes have one candidate; comma-separated attributes such as {@code srcset} may carry several, and a single
 dangerous candidate must not be smuggled through beside safe ones.
 */
private boolean isSafeAttributeProtocol(Element el, Attribute attr, Set<Protocol> protocols) {
    String value = attr.getValue();
    if (multiValueUrlAttribute(attr.getKey())) {
        int len = value.length();
        int start = 0;
        boolean found = false;
        for (int i = 0; i <= len; i++) {
            if (i == len || value.charAt(i) == ',') {
                String candidate = stripCandidateDescriptor(value.substring(start, i));
                if (!candidate.isEmpty() && !isSafeProtocol(candidate, protocols, true)) return false;
                if (!candidate.isEmpty()) found = true;
                start = i + 1;
            }
        }
        return found; // an empty value has no candidates to enforce a protocol on
    }
    String protocolValue = getProtocolValue(el, attr);
    return protocolValue.isEmpty() || isSafeProtocol(protocolValue, protocols, false);
}

private boolean isSafeProtocol(String value, Set<Protocol> protocols, boolean rawCandidate) {
    // trim the ASCII whitespace (SP, TAB, LF, CR, FF) that browsers ignore around a URL
    int start = 0;
    int end = value.length();
    while (start < end && isHtmlWhitespace(value.charAt(start))) start++;
    while (end > start && isHtmlWhitespace(value.charAt(end - 1))) end--;
    if (start == end) return false;
