private static String stripCandidateDescriptor(String candidate) {
    int len = candidate.length();
    int i = 0;
    while (i < len && isHtmlWhitespace(candidate.charAt(i))) i++;
    int start = i;
    while (i < len && !isHtmlWhitespace(candidate.charAt(i))) i++;
    return candidate.substring(start, i);
