        // relatives without preserve => resolved absolute
        ck("abs rel",     "<a href=\"https://example.com/foo/bar\" rel=\"nofollow\">x</a>", clean("<a href=foo/bar>x</a>", basic));
        ck("abs root",    "<a href=\"https://example.com/foo\" rel=\"nofollow\">x</a>", clean("<a href=/foo>x</a>", basic));
        ck("abs proto",   "<a href=\"https://example.com/x\" rel=\"nofollow\">x</a>", clean("<a href=//example.com/x>x</a>", basic));
        ck("norel base",  "<a rel=\"nofollow\">x</a>", Jsoup.clean("<a href=/foo>x</a>", basic));

        // hostless rules preserved
        ck("hostless httpbase", "<a rel=\"nofollow\">Link</a>", clean("<a href='https:/foo/bar'>Link</a>", basic));
        ck("hostless httpsbase","<a href=\"https:/foo/bar\">Link</a>", Jsoup.clean("<a href='https:/foo/bar'>Link</a>", "https://example.com/a/b", basicRel));

        // custom protocols
        Safelist custom = Safelist.basicWithImages().addProtocols("img", "src", "cid", "data");
        ck("cid", "<img src=\"cid:12345\"> ", (clean("<img src='cid:12345' /> ", custom)));
        ck("data allowed", "<img src=\"data:gzzt\">", clean("<img src='data:gzzt' />", custom));
        Safelist tel = Safelist.none().addTags("a").addAttributes("a","href").addProtocols("a","href","tel");
        ck("tel", "<a href=\"tel:+123\"></a>", clean("<a href=tel:+123></a>", tel));

        // empty / missing / plain
        ck("empty href",  "<a rel=\"nofollow\">x</a>", clean("<a href=>x</a>", basic));
        ck("bool href",   "<a rel=\"nofollow\">x</a>", clean("<a href>x</a>", basic));
        ck("plain no colon in rel", "<a href=\"somethingweird\">x</a>", cleanRel("<a href=somethingweird>x</a>", basicRel));

        // anchor protocol "#"
        Safelist anchor = Safelist.relaxed().addProtocols("a", "href", "#");
        ck("anchor ok",   "<a href=\"#valid\">Valid anchor</a>", clean("<a href=\"#valid\">Valid anchor</a>", anchor));
        ck("anchor ws",   "<a>Invalid anchor</a>", clean("<a href=\"#anchor with spaces\">Invalid anchor</a>", anchor));

        // --- element & sibling attrs preserved; only bad attr dropped
        ck("keep others", "<a href=\"https://example.com/\" title=\"hi\" rel=\"nofollow\">x</a>",
            clean("<a href=\"https://example.com/\" title=hi onclick=\"evil()\">x</a>", Safelist.relaxed()));
        ck("img other attr", "<img alt=\"hi\" src=\"https://example.com/a.png\">",
            clean("<img src=\"https://example.com/a.png\" alt=hi onerror=1>", img));
        ck("js src keep alt", "<img alt=\"x\">", clean("<img src=javascript:1 alt=x>", img));

        // independence per attribute
        Safelist indep = Safelist.none().addTags("a")
            .addAttributes("a","href","src")
            .addProtocols("a","href","http","https")
            .addProtocols("a","src","ftp");
