import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Safelist;

public class Verify {
    static int fails = 0;
    static void ck(String label, String expected, String actual) {
        boolean ok = expected.equals(actual);
        if (!ok) { fails++; System.out.println("FAIL " + label + "\n   exp=[" + expected + "]\n   got=[" + actual + "]"); }
        else System.out.println("ok   " + label);
    }
    // default base is example.com; same-host links therefore do not get rel=nofollow (existing Cleaner behavior)
    static String clean(String html, Safelist sl) { return Jsoup.clean(html, "https://example.com/page/index.html", sl); }
    static String cleanNoBase(String html, Safelist sl) { return Jsoup.clean(html, sl); }

    public static void main(String[] a) {
        Safelist basic = Safelist.basic();
        Safelist basicRel = Safelist.basic().preserveRelativeLinks(true);
        Safelist imgRel = Safelist.basicWithImages().preserveRelativeLinks(true);
        Safelist img = Safelist.basicWithImages();
        Safelist srcset = Safelist.basicWithImages()
            .addAttributes("img", "srcset")
            .addProtocols("img", "srcset", "http", "https");
        Safelist srcsetRel = new Safelist(srcset).preserveRelativeLinks(true);

        // --- dangerous single protocols removed in all obfuscations (attr dropped, element/text kept)
        ck("js plain",    "<a>x</a>", clean("<a href=javascript:alert(1)>x</a>", basic));
        ck("js mixedcase","<a>x</a>", clean("<a href=JaVaScRiPt:alert(1)>x</a>", basic));
        ck("js upper",    "<a>x</a>", clean("<a href=JAVASCRIPT:1>x</a>", basic));
        ck("js lead ws",  "<a>x</a>", clean("<a href=\"  javascript:1\">x</a>", basic));
        ck("js trail ws", "<a>x</a>", clean("<a href=\"javascript:1  \">x</a>", basic));
        ck("js tab nl",   "<a>x</a>", clean("<a href=\"\t\njavascript:1\r\n\">x</a>", basic));
        ck("js ff",       "<a>x</a>", clean("<a href=\"java\fscript:1\">x</a>", basic));
        ck("js ctrl mid", "<a>x</a>", clean("<a href=\"java&#x09;script:1\">x</a>", basic));
        ck("js SOH mid",  "<a>x</a>", clean("<a href=\"java&#x01;script:1\">x</a>", basic));
        ck("js cr ent",   "<a>x</a>", clean("<a href=\"&#0013;ja&Tab;va&Tab;script&#0010;:1\">x</a>", basic));
        ck("js colon ent","<a>x</a>", cleanNoBase("<a href=\"java&Tab;script&colon;1\">x</a>", basicRel));
        ck("js bs 1",     "<a>x</a>", clean("<a href=\"javascript\\:1\">x</a>", basic));
        ck("js bs 2",     "<a>x</a>", clean("<a href=\"javascript:\\\\1\">x</a>", basic));
        ck("js pct s",    "<a>x</a>", clean("<a href=\"java%73cript:1\">x</a>", basic));
        ck("js pct j",    "<a>x</a>", clean("<a href=\"%6Aavascript:1\">x</a>", basic));
        ck("js DEL",      "<a>x</a>", clean("<a href=\"java\u007fscript:1\">x</a>", basic));
        ck("data a",      "<a>x</a>", clean("<a href=data:text/html,x>x</a>", basic));
        ck("vb a",        "<a>x</a>", clean("<a href=vbscript:1>x</a>", basic));
        ck("js relmode",  "<a>x</a>", cleanNoBase("<a href=javascript:1>x</a>", basicRel));
        ck("js rel pct",  "<a>x</a>", cleanNoBase("<a href=java%73cript:1>x</a>", basicRel));
        ck("js rel DEL",  "<a>x</a>", cleanNoBase("<a href=java\u007fscript:1>x</a>", basicRel));
        ck("js rel lead", "<a>x</a>", cleanNoBase("<a href=\"  javascript:1\">x</a>", basicRel));
        ck("js nbsp",     "<a>x</a>", clean("<a href=\"java script:1\">x</a>", basic));
        ck("js zwsp",     "<a>x</a>", clean("<a href=\"java​script:1\">x</a>", basic));

        // --- safe protocols kept incl path/query/fragment
        ck("https full",  "<a href=\"https://example.com/a?b=1#c\">x</a>", clean("<a href=\"https://example.com/a?b=1#c\">x</a>", basic));
        ck("http upper",  "<a href=\"https://Example.COM/x\" rel=\"nofollow\">x</a>", clean("<a href=HTTPS://Example.COM/x>x</a>", basic));
        ck("ftp",         "<a href=\"ftp://example.com/f\" rel=\"nofollow\">x</a>", clean("<a href=ftp://example.com/f>x</a>", basic));
        ck("mailto",      "<a href=\"mailto:a@b.com\">x</a>", clean("<a href=mailto:a@b.com>x</a>", basic));
        ck("multi colon", "<a href=\"http://evil.com/:javascript:x\" rel=\"nofollow\">x</a>", clean("<a href=\"http://evil.com/:javascript:x\">x</a>", basic));

        // --- relatives (preserve)
        ck("rel path",    "<a href=\"foo/bar.html\">x</a>", cleanNoBase("<a href=foo/bar.html>x</a>", basicRel));
        ck("rel root",    "<a href=\"/foo/bar\">x</a>", cleanNoBase("<a href=/foo/bar>x</a>", basicRel));
        ck("rel frag",    "<a href=\"#section\">x</a>", cleanNoBase("<a href=#section>x</a>", basicRel));
        ck("rel proto",   "<a href=\"//example.com/x\">x</a>", cleanNoBase("<a href=//example.com/x>x</a>", basicRel));
        ck("rel q frag",  "<a href=\"foo?a=1#b\">x</a>", cleanNoBase("<a href=foo?a=1#b>x</a>", basicRel));
        // relatives without preserve => resolved absolute
        ck("abs rel",     "<a href=\"https://example.com/page/foo/bar\">x</a>", clean("<a href=foo/bar>x</a>", basic));
        ck("abs root",    "<a href=\"https://example.com/foo\">x</a>", clean("<a href=/foo>x</a>", basic));
        ck("abs proto",   "<a href=\"https://example.com/x\">x</a>", clean("<a href=//example.com/x>x</a>", basic));
        ck("norel base",  "<a>x</a>", cleanNoBase("<a href=/foo>x</a>", basic));

        // hostless rules preserved
        ck("hostless cross-scheme", "<a>Link</a>", Jsoup.clean("<a href='https:/foo/bar'>Link</a>", "http://example.com/a/b", basic));
        ck("hostless same-scheme",  "<a href=\"https:/foo/bar\">Link</a>", Jsoup.clean("<a href='https:/foo/bar'>Link</a>", "https://example.com/a/b", basicRel));

        // custom protocols
        Safelist custom = Safelist.basicWithImages().addProtocols("img", "src", "cid", "data");
        ck("cid", "<img src=\"cid:12345\">", clean("<img src='cid:12345' />", custom).trim());
        ck("data allowed", "<img src=\"data:gzzt\">", clean("<img src='data:gzzt' />", custom));
        Safelist tel = Safelist.none().addTags("a").addAttributes("a","href").addProtocols("a","href","tel");
        ck("tel", "<a href=\"tel:+123\"></a>", clean("<a href=tel:+123></a>", tel));

        // empty / missing / plain
        ck("empty href",  "<a>x</a>", clean("<a href=>x</a>", basic));
        ck("bool href",   "<a>x</a>", clean("<a href>x</a>", basic));
        ck("plain no colon in rel", "<a href=\"somethingweird\">x</a>", cleanNoBase("<a href=somethingweird>x</a>", basicRel));

        // anchor protocol "#"
        Safelist anchor = Safelist.relaxed().addProtocols("a", "href", "#");
        ck("anchor ok",   "<a href=\"#valid\">Valid anchor</a>", cleanNoBase("<a href=\"#valid\">Valid anchor</a>", anchor));
        ck("anchor ws",   "<a>Invalid anchor</a>", cleanNoBase("<a href=\"#anchor with spaces\">Invalid anchor</a>", anchor));

        // --- element & sibling attrs preserved; only bad attr dropped
        ck("keep others", "<a href=\"https://example.com/\" title=\"hi\">x</a>",
            clean("<a href=\"https://example.com/\" title=hi onclick=\"evil()\">x</a>", Safelist.relaxed()));
        ck("img other attr", "<img src=\"https://example.com/a.png\" alt=\"hi\">",
            clean("<img src=\"https://example.com/a.png\" alt=hi onerror=1>", img));
        ck("js src keep alt", "<img alt=\"x\">", clean("<img src=javascript:1 alt=x>", img));

        // independence per attribute
        Safelist indep = Safelist.none().addTags("a")
            .addAttributes("a","href","src")
            .addProtocols("a","href","http","https")
            .addProtocols("a","src","ftp");
        ck("indep keep",  "<a src=\"ftp://example.com/f\">z</a>", clean("<a href=javascript:1 src=ftp://example.com/f>z</a>", indep));
        ck("indep drop",  "<a href=\"https://example.com/\">z</a>", clean("<a href=https://example.com/ src=https://notallowed.com/>z</a>", indep));

        // form action
        Safelist form = Safelist.none().addTags("form").addAttributes("form","action").addProtocols("form","action","https");
        ck("form js",     "<form></form>", clean("<form action=JAVASCRIPT:1></form>", form));
        ck("form http drop","<form></form>", clean("<form action=http://example.com/>", form));
        ck("form https",  "<form action=\"https://example.com/\"></form>", clean("<form action=https://example.com/></form>", form));

        // --- srcset smuggling: any dangerous candidate fails the whole attribute closed
        ck("set safe+js",   "<img>",
            clean("<img srcset='https://ok.com/b.jpg 2x, javascript:alert(1) 1x'>", srcset));
        ck("set js+safe",   "<img>",
            clean("<img srcset='javascript:alert(1) 1x, https://ok.com/b.jpg 2x'>", srcset));
        ck("set rel+js",    "<img>",
            clean("<img srcset='/safe.jpg 1x, javascript:alert(1) 2x'>", srcset));
        ck("set data 2nd",  "<img>",
            clean("<img srcset='https://ok.com/b.jpg, data:text/html,evil'>", srcset));
        ck("set case js",   "<img>",
            clean("<img srcset='https://ok.com/b.jpg, JaVaScRiPt:x'>", srcset));
        ck("set mid js",    "<img>",
            clean("<img srcset='a.jpg 1x, javascript:x 2x, https://ok.com/c.jpg 3x'>", srcset));
        ck("set no desc",   "<img>",
            clean("<img srcset='https://ok.com/b.jpg,javascript:1'>", srcset));
        ck("set pct",       "<img>",
            clean("<img srcset='https://ok.com/b.jpg, java%73cript:1'>", srcset));
        ck("set DEL",       "<img>",
            clean("<img srcset='https://ok.com/b.jpg, java\u007fscript:1'>", srcset));
        ck("set all safe abs","<img srcset=\"https://example.com/page/a.jpg 1x, https://ok.com/c.jpg 2x\">",
            clean("<img srcset='a.jpg 1x, https://ok.com/c.jpg 2x'>", srcset));
        // srcset preserveRelative
        ck("set rel keep",  "<img srcset=\"a.jpg 1x, /b.jpg 2x, //cdn.com/c 3x\">",
            cleanNoBase("<img srcset='a.jpg 1x, /b.jpg 2x, //cdn.com/c 3x'>", srcsetRel));
        ck("set rel js",    "<img>",
            cleanNoBase("<img srcset='a.jpg, javascript:1'>", srcsetRel));
        ck("set rel proto", "<img srcset=\"//ok.com/a, /b.jpg\">",
            cleanNoBase("<img srcset='//ok.com/a, /b.jpg'>", srcsetRel));
        // https-only srcset
        Safelist httpsOnly = Safelist.none().addTags("img").addAttributes("img","srcset").addProtocols("img","srcset","https");
        ck("set https only","<img>",
            clean("<img srcset='https://ok.com/b.jpg, http://insecure.com/a.jpg'>", httpsOnly));

        // --- idempotency: twice == once
        String[][] idem = {
            {"basic", "<a href=\"https://example.com/a?b=1#c\">x</a>"},
            {"srcset", "<img srcset=\"https://example.com/page/a.jpg 1x, https://ok.com/c.jpg 2x\">"},
            {"rel", "<a href=\"//example.com/x\">x</a>"},
        };
        for (String[] tc : idem) {
            Safelist sl = tc[0].equals("srcset") ? srcset : (tc[0].equals("rel") ? basicRel : basic);
            String base = tc[0].equals("rel") ? "" : "https://example.com/page/index.html";
            String once = Jsoup.clean(tc[1], base, sl);
            String twice = Jsoup.clean(once, base, sl);
            ck("idempotent " + tc[0], once, twice);
        }

        // output reparseable + queryable, structure stable
        Document d = Jsoup.parse(clean("<p>before<a id=l href=https://example.com/ title=t>x</a>after</p>",
            Safelist.relaxed().addAttributes("a","id")));
        ck("selector", "x", d.select("a#l").text());
        ck("text kept", "beforexafter", d.body().text());

        // validity API agrees
        String bad = "<a href=javascript:1>x</a>";
        ck("isValid false", "false", String.valueOf(Jsoup.isValid(bad, basic)));
        ck("isValid true",  "true",  String.valueOf(Jsoup.isValid("<a href=https://example.com/>x</a>", basic)));

        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
        if (fails != 0) System.exit(1);
    }
}

