        ck("text kept", "beforexafter", d.body().text());

        // validity API agrees
        String bad = "<a href=javascript:1>x</a>";
        ck("isValid false", "false", String.valueOf(Jsoup.isValid(bad, basic)));
        ck("isValid true",  "true",  String.valueOf(Jsoup.isValid("<a href=https://example.com/>x</a>", basic)));

        System.out.println(fails == 0 ? "ALL PASS" : fails + " FAILURES");
        if (fails != 0) System.exit(1);
    }
}

