import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Edge {
    static void t(String label, String html, Safelist sl, String base) {
        System.out.println(label + " => [" + Jsoup.clean(html, base, sl) + "]");
    }
    public static void main(String[] a) {
        Safelist basic = Safelist.basic();
        Safelist rel = Safelist.basic().preserveRelativeLinks(true);
        String b = "https://example.com/page/index.html";
        t("colon in path",  "<a href=/foo:bar>x</a>", basic, b);
        t("colon seg2",     "<a href=a/b:c>x</a>", basic, b);
        t("colon query",    "<a href=search?q=a:b>x</a>", basic, b);
        t("space in path",  "<a href=/foo%20bar>x</a>", basic, b);
        t("raw space path", "<a href=\"/foo bar.html\">x</a>", basic, b);
        t("colon path rel", "<a href=a/b:c>x</a>", rel, "");
        t("pct in path",    "<a href=/foo%20bar%20baz>x</a>", basic, b);
        t("digit start",    "<a href=123:45>x</a>", basic, b);
        t("pct scheme",     "<a href=java%73cript:1>x</a>", basic, b);
        t("bs scheme",      "<a href=javascript\\:1>x</a>", basic, b);
        t("space scheme",   "<a href=\"java script:1\">x</a>", basic, b);
        t("tab scheme",     "<a href=\"java\tscript:1\">x</a>", basic, b);
        t("http encoded colon", "<a href=http%3a//evil.com/>x</a>", basic, b);
        t("at trick",       "<a href=https://safe.com@evil.com>x</a>", basic, b);
        t("frag colon",     "<a href=#sec:1>x</a>", Safelist.relaxed().addProtocols("a","href","#"), "");
        t("mailto-ish rel", "<a href=foo:bar@baz>x</a>", basic, b);
    }
}

