import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class Final {
    static void t(String label, String out, String exp) {
        System.out.println((out.equals(exp) ? "ok   " : "FAIL ") + label + " => " + out + (out.equals(exp) ? "" : "  EXPECTED " + exp));
    }
    public static void main(String[] a) {
        String b = "https://example.com/page/index.html";
        Safelist http = Safelist.none().addTags("a").addAttributes("a","href")
            .addProtocols("a","href","http","https","ftp");
        t("lead-tab https",
            Jsoup.clean("<a href=\"\thttps://ok.com/x\">x</a>", b, http),
            "<a href=\"https://ok.com/x\">x</a>");
        t("lead-sp https",
            Jsoup.clean("<a href=\" https://ok.com/x\">x</a>", b, http),
            "<a href=\"https://ok.com/x\">x</a>");
        t("FTP upper",
            Jsoup.clean("<a href=FTP://ok.com/f>x</a>", b, http),
            "<a href=\"FTP://ok.com/f\">x</a>");
        t("js no rest",
            Jsoup.clean("<a href=javascript:>x</a>", b, http), "<a>x</a>");
        t("just colon",
            Jsoup.clean("<a href=:foo>x</a>", b, http), "<a>x</a>");
        t("http colon only",
            Jsoup.clean("<a href=http:foo>x</a>", b, http), "<a href=\"http:foo\">x</a>");
        // encoded comma inside a srcset URL is part of the URL
        Safelist ss = Safelist.none().addTags("img").addAttributes("img","srcset")
            .addProtocols("img","srcset","http","https");
        t("set encoded comma",
            Jsoup.clean("<img srcset=\"https://ok.com/a%2Cb.jpg 1x\">", b, ss),
            "<img srcset=\"https://ok.com/a%2Cb.jpg 1x\">");
        t("set empty segment",
            Jsoup.clean("<img srcset=\"https://ok.com/a, , javascript:1\">", b, ss),
            "<img>");
        t("set trailing comma safe",
            Jsoup.clean("<img srcset=\"https://ok.com/a,\">", b, ss),
            "<img srcset=\"https://ok.com/a,\">");
        t("set only separators",
            Jsoup.clean("<img srcset=\", ,\">", b, ss),
            "<img>");
        // imagesrcset
        Safelist iss = Safelist.none().addTags("link").addAttributes("link","imagesrcset")
            .addProtocols("link","imagesrcset","http","https");
        t("imagesrcset js",
            Jsoup.clean("<link imagesrcset=\"https://ok.com/a, javascript:1\">", b, iss),
            "<link>");
        t("imagesrcset ok",
            Jsoup.clean("<link imagesrcset=\"/a 1x, //cdn/b 2x\">", b, iss),
            "<link imagesrcset=\"https://example.com/a 1x, https://cdn/b 2x\">");
        // backslash after scheme allowed http (browsers convert \ to /) - Java resolve behavior
        t("http bs host",
            Jsoup.clean("<a href=\"https:/\\\\evil.com\">x</a>", b, http),
            Jsoup.clean("<a href=\"https:/\\\\evil.com\">x</a>", b, http));
        // data with uppercase percent
        Safelist img = Safelist.basicWithImages();
        t("img data pct",
            Jsoup.clean("<img src=DATA:text/plain,x>", img), "<img>");
        // tab/newline inside otherwise-https
        t("https tab host",
            Jsoup.clean("<a href=\"https://ok.com/x\t\">x</a>", b, http),
            "<a href=\"https://ok.com/x\">x</a>");
        // multiple colon scheme area
        t("http fake prefix",
            Jsoup.clean("<a href=\"javascript:https://evil.com\">x</a>", b, http), "<a>x</a>");
        t("https fake js path",
            Jsoup.clean("<a href=\"https://safe.com/x#javascript:alert(1)\">x</a>", b, http),
            "<a href=\"https://safe.com/x#javascript:alert(1)\">x</a>");
    }
}

